create table if not exists public.platform_incidents(id uuid primary key default gen_random_uuid(),title text not null check(length(trim(title)) between 5 and 160),summary text not null check(length(trim(summary)) between 10 and 2000),severity text not null check(severity in('minor','major','critical')),status text not null default 'investigating' check(status in('investigating','identified','monitoring','resolved')),affected_services text[] not null default '{}',started_at timestamptz not null default now(),resolved_at timestamptz,owner_id uuid references auth.users(id),created_by uuid not null default auth.uid() references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.platform_incident_updates(id uuid primary key default gen_random_uuid(),incident_id uuid not null references public.platform_incidents(id) on delete cascade,message text not null check(length(trim(message)) between 3 and 2000),status text check(status in('investigating','identified','monitoring','resolved')),created_by uuid not null default auth.uid() references auth.users(id),created_at timestamptz not null default now());
alter table public.platform_incidents enable row level security;alter table public.platform_incident_updates enable row level security;
create policy "plataforma gerencia incidentes" on public.platform_incidents for all to authenticated using(public.is_platform_admin()) with check(public.is_platform_admin());
create policy "plataforma gerencia atualizacoes incidente" on public.platform_incident_updates for all to authenticated using(public.is_platform_admin()) with check(public.is_platform_admin());
create or replace function public.platform_update_incident(p_id uuid,p_status text,p_message text) returns void language plpgsql security definer set search_path=public as $$ begin if not is_platform_admin() then raise exception 'Acesso restrito';end if;if p_status not in('investigating','identified','monitoring','resolved') then raise exception 'Status inválido';end if;update platform_incidents set status=p_status,updated_at=now(),resolved_at=case when p_status='resolved' then now() else null end where id=p_id;if not found then raise exception 'Incidente não encontrado';end if;insert into platform_incident_updates(incident_id,message,status)values(p_id,trim(p_message),p_status);insert into audit_log(user_id,action,collection,record_id,changes)values(auth.uid(),'update','platform_incidents',p_id::text,jsonb_build_object('status',p_status));end;$$;
revoke all on function public.platform_update_incident(uuid,text,text) from public,anon;grant execute on function public.platform_update_incident(uuid,text,text) to authenticated;
